struct SeqHeader: Codable { let seqID: String; let pos: Int; let size: Int }

actor Reassembler {
    private var groups: [String: [Data?]] = [:]
    func add(_ h: SeqHeader, _ part: Data) -> Data? {
        var parts = groups[h.seqID] ?? Array(repeating: nil, count: h.size)
        parts[h.pos - 1] = part
        groups[h.seqID] = parts.allSatisfy { $0 != nil } ? nil : parts
        return parts.allSatisfy { $0 != nil } ? parts.compactMap { $0 }.reduce(Data(), +) : nil
    }
}
